from lib import *
S = SS('l64')
steps = [
    step("git submodule add(本地路径要加 -c protocol.file.allow=always)之后,暂存区多了两项:A  .gitmodules 和 A  vendor/lib。.gitmodules 内容是 [submodule \"vendor/lib\"] 加 path = vendor/lib 和 url = …;.git/config 里也多了 submodule.vendor/lib.url 和 submodule.vendor/lib.active = true。子模块目录里的 .git 是一个文件:gitdir: ../../.git/modules/vendor/lib——子仓库真正的 git 目录(HEAD、config、objects、refs…)被放在超级项目的 .git/modules/vendor/lib 下。git ls-files -s 里 vendor/lib 的模式是 160000。", t=tl(S(1)), mark=lidx(S(1), 'A  .gitmodules', 'gitdir: ../../.git/modules/vendor/lib', '160000'), done=lidx(S(1), '[submodule "vendor/lib"]', 'path = vendor/lib', 'lib.active true', 'HEAD config description'), kv=KV([['.gitmodules', '路径与 URL,会提交'], ['.git/config', 'URL 与 active,本地'], ['.git/modules/', '子仓库真正的 git 目录'], ['子模块里的 .git', '一个指回去的文件']], ['.git/modules/'])),
    step("提交之后,超级项目的 tree 里只有三个条目:100644 .gitmodules、100644 app.txt、160000 commit vendor/lib——子模块在 tree 里就是一个 160000 的 commit 条目,值是子仓库的一个提交 hash,没有任何子仓库内容。这个 hash 与子仓库当前 HEAD 一致(True)。", t=tl(S(2)), mark=lidx(S(2), '160000 commit <sha40>'), done=lidx(S(2), 'app.txt', '.gitmodules', '记录的 hash == 子仓库当前 HEAD: True'), kv=KV([['超级项目', '只记录子仓库的 commit hash'], ['160000', 'gitlink 条目'], ['内容', '在子仓库里,不在超级项目里']], ['160000'])),
    step("子仓库有了新提交(lib v2),在子模块里 fetch 并检出之后,超级项目的 git status 显示 M vendor/lib(子模块里的 HEAD 与记录的不同);git diff --submodule=log 展开成 Submodule vendor/lib <旧>..<新>: > lib v2;git submodule status 以 + 开头(+<sha> vendor/lib (remotes/origin/HEAD))。只有在超级项目里 git add vendor/lib 并提交,新的 hash 才被记下来。", t=tl(S(3)), mark=lidx(S(3), 'M vendor/lib', 'Submodule vendor/lib', '> lib v2', '+<sha40>'), done=lidx(S(3), 'git status --short'), kv=KV([['M vendor/lib', '子模块 HEAD 与记录的不同'], ['diff --submodule=log', '展开成提交列表'], ['+', 'submodule status 里表示不一致']], ['M vendor/lib'])),
    step("普通 clone 之后子模块目录是空的:ls vendor/lib 文件数 0;git submodule status 以 - 开头(-<sha> vendor/lib,表示未初始化);.git/config 里 submodule 配置项数 0。git submodule update --init 才初始化并克隆,输出 Submodule path 'vendor/lib': checked out '<sha>',把子模块检出到超级项目记录的那个提交,处于 HEAD detached at …(分离 HEAD)状态。", t=tl(S(4)), mark=lidx(S(4), '文件数: 0', '-<sha40> vendor/lib', '配置项数: 0'), done=lidx(S(4), 'checked out', 'HEAD detached at', 'lib.txt'), kv=KV([['clone 后', '子模块目录为空'], ['-', '未初始化'], ['update --init', '克隆并检出记录的提交'], ['HEAD', '分离状态']], ['update --init'])),
    step("切换超级项目的提交不会自动更新子模块:git checkout HEAD~1(回到记录 v1 的那次提交)后,git submodule status 显示 +<sha> vendor/lib,git status 显示 M vendor/lib(子模块仍停在 v2)。执行 git submodule update 才把它检出到记录的提交(checked out '<sha>'),vendor/lib/lib.txt 的内容变回 v1。可以设置 submodule.recurse=true 或 checkout --recurse-submodules 让它自动跟随。", t=tl(S(5)), mark=lidx(S(5), '+<sha40> vendor/lib', ' M vendor/lib'), done=lidx(S(5), 'checked out', 'v1'), kv=KV([['切换分支', '子模块不会自己跟着变'], ['+', '提醒你不一致'], ['git submodule update', '检出到记录的提交']], ['git submodule update'])),
    step("git clone --recurse-submodules 一步到位:vendor/lib 里有 lib.txt,git submodule status 的开头是空格(已初始化且一致)。.gitmodules 的 URL 改了(git config -f .gitmodules submodule.vendor/lib.url …),.git/config 里的 URL 仍是旧的(…/l64lib.git),要执行 git submodule sync 才同步成新的 https://example.invalid/lib.git。.gitmodules 是提交进仓库的“建议”,.git/config 是本机实际使用的值。", t=tl(S(6)), mark=lidx(S(6), 'sync 之后', 'https://example.invalid/lib.git'), done=lidx(S(6), 'lib.txt', '改了 .gitmodules 之后'), kv=KV([['--recurse-submodules', 'clone 时一并初始化'], ['.gitmodules', '随仓库提交的 URL'], ['.git/config', '本机实际用的 URL'], ['submodule sync', '把前者同步到后者']], ['submodule sync'])),
]
A = mkarti('l64', 64, 'Git,submodule,gitlink,.gitmodules,真实验证,动画演示',
    '实测子模块:submodule add 留下 .gitmodules、.git/config 的 submodule.* 项、子模块目录里指向 .git/modules/ 的 .git 文件;超级项目的 tree 里只有一个 160000 条目,值是子仓库的提交 hash;子仓库有新提交时 status 显示 M、submodule status 以 + 开头;普通 clone 后子模块为空(-),update --init 才检出记录的提交(分离 HEAD);切换超级项目的提交不会自动更新子模块;.gitmodules 改 URL 要 sync。',
    'git submodule 把另一个仓库“嵌”在当前仓库里,它在 .git 里到底留下什么、超级项目的提交里记了什么、为什么 clone 之后子模块是空的?这篇用两个本机仓库把整个生命周期走一遍。',
    [('160000', '超级项目的 tree 里子模块的条目模式,值是子仓库的一个提交 hash,只此而已'), ('- + 空格', 'git submodule status 的前缀:- 未初始化,+ 与记录的不同,空格 一致'), ('.git/modules/', '子仓库真正的 git 目录放在超级项目的 .git 里,子模块目录里只有一个 .git 文件')],
    [('add 做了什么', '<p>创建 <code>.gitmodules</code>(路径与 URL,提交进仓库),在 <code>.git/config</code> 写下 <code>submodule.&lt;名&gt;.url</code> 与 <code>active</code>,把子仓库克隆到 <code>.git/modules/&lt;路径&gt;</code>,并在子模块目录放一个 <code>.git</code> 文件(<code>gitdir: …</code>)指回去。暂存区里子模块是 <code>160000</code> 条目。</p>'),
     ('超级项目记什么', '<p>超级项目的 tree 里子模块只是一个 160000 的 commit 条目,值是子仓库的某个提交 hash。子仓库的任何内容都不在超级项目里。</p>'),
     ('新提交', '<p>子仓库有新提交且子模块检出到它时,超级项目显示 <code>M</code>(<code>git diff --submodule=log</code> 展开);只有在超级项目里 <code>git add</code> 并提交,新 hash 才被记录。</p>'),
     ('clone 之后', '<p>普通 clone 得到空目录,<code>git submodule status</code> 以 <code>-</code> 开头。<code>git submodule update --init</code> 才克隆并把子模块检出到记录的提交(分离 HEAD)。<code>clone --recurse-submodules</code> 一步完成。</p>'),
     ('切换不跟随', '<p>切换超级项目的分支或提交不会自动更新子模块,<code>status</code> 里以 <code>+</code> 提醒不一致;<code>git submodule update</code>(或 <code>submodule.recurse=true</code>)让它对齐。</p>'),
     ('URL', '<p><code>.gitmodules</code> 是随仓库提交的,<code>.git/config</code> 是本机实际使用的;改了前者要 <code>git submodule sync</code> 才同步到后者。</p>')],
    steps,
    [ENV_I_GIT + '。子模块的“远程”是本机的裸仓库(file 路径),因此每次 submodule add / update 都带 -c protocol.file.allow=always(新版 git 默认禁止子模块用 file 协议);输出里 hash、URL 做了替换',
     '没有验证:嵌套子模块(子模块里的子模块);git submodule update --remote 追踪分支;submodule 的 branch 配置;删除子模块的完整步骤(git rm + .git/modules 清理);子模块的 shallow 克隆;git worktree 与子模块;submodule.recurse 的完整效果'],
    '子模块')
